"use strict";
const {PrototypeAdapter,buildSearchView,restoreInvoker,stateCopy}=FamilyPassportModel;
const dataAdapter=new PrototypeAdapter();
const MOCK_NOTICE="Synthetic document examples — household settings are saved in your isolated local database.";
const state={route:"auth",scenario:"default",recordTab:"home",recordDetail:null,query:"",searchResult:null,selectedSourceId:null,sourceInvoker:null,helpInvoker:null,connectorPreview:{},authMode:"signin",previewSignedIn:false,authReady:false,authBusy:false,authMessage:"",authError:"",authUser:null,householdData:null,dataBusy:false,dataError:"",ocrBusy:false,ocrError:"",ocrCandidate:null};
const screen=document.querySelector("#screen"),statusRegion=document.querySelector("#app-status"),scenarioPanel=document.querySelector("#scenario-panel"),scenarioToggle=document.querySelector("#scenario-toggle"),scenarioSelect=document.querySelector("#scenario"),helpDialog=document.querySelector("#help-dialog");
const esc=value=>String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const pageHead=(eyebrow,title,lede,action="")=>`<header class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1 tabindex="-1">${title}</h1><p class="lede">${lede}</p></div>${action}</header>`;
const item=(x,action="Open",attrs="")=>`<li class="record-item"><span class="item-icon" aria-hidden="true">${x.kind}</span><span class="item-copy"><strong>${x.name||x.title}</strong><small>${x.detail}</small></span><button class="quiet-button" type="button" ${attrs}>${action}</button></li>`;
function announce(message){statusRegion.textContent="";requestAnimationFrame(()=>statusRegion.textContent=message)}
function openHelp(invoker=document.activeElement){
  state.helpInvoker=invoker;
  const help={auth:["Choose Sign in or Create account, then preview either email or Google entry.","No credential is sent or stored; live authentication waits for an approved provider."],home:["Choose the first next action; each opens a representative synthetic task.","If Home is stale or offline, verify the exact source before relying on dates."],records:["Use the tabs to browse authorised People, Home and Vehicle examples, then open a representative detail.","Restricted records never reveal hidden names or counts."],add:["Choose one source and preview only. This prototype never requests permission or selects a real file.","Cancel or retry errors without retaining a selection."],review:["Read the source evidence first, correct the suggestion if needed, then explicitly confirm, skip or reject it.","Conflicting or stale evidence must be compared; no critical value is silently chosen."],search:["Ask about the synthetic home insurance or Toyota WOF. Every answer cites an exact example source.","When no source supports a question, Search abstains and lets you refine it."],connections:["Compare the exact access Family Documents would request from Google Drive or OneDrive.","This preview never signs in, opens a provider window, stores a token or reads a file."],household:["Invite a family member, choose a role, then preview category, entity or document access.","Invites and permission changes are demonstrations only and disappear when the page reloads."]}[state.route]||["This is a synthetic preview.","Return to Home and try again."];
  document.querySelector("#help-content").innerHTML=`<p>${help[0]}</p><p><strong>Recovery:</strong> ${help[1]}</p><p>No files, accounts or household data are connected.</p>`;
  helpDialog.showModal();
}
helpDialog.addEventListener("close",()=>{state.helpInvoker?.focus?.();state.helpInvoker=null});
function stateView(route,kind){
  const [title,copy]=stateCopy(route,kind,{query:state.query});
  const icon={loading:"···",empty:"○",error:"!",restricted:"―",offline:"↯",conflict:"≠",stale:"↻"}[kind],klass=["error","conflict"].includes(kind)?"error":"";
  const preserved=route==="records"?`<p class="pill">Selected category: ${esc(state.recordTab)}</p>`:route==="search"&&state.query?`<p class="pill">Preserved query: ${esc(state.query)}</p>`:route==="review"?'<p class="pill attention">Proposed date remains unconfirmed</p>':"";
  let actions="";
  if(kind==="restricted")actions='<button class="secondary-button" type="button" data-state-help>Open help</button>';
  else if(kind==="loading")actions='<button class="secondary-button" type="button" data-route-button="home">Cancel and return home</button>';
  else if(kind==="empty"&&route!=="search")actions='<button class="primary-button" type="button" data-route-button="add">Add information</button>';
  else if(kind==="conflict"&&route==="review")actions='<button class="primary-button" type="button" data-reset-state>Compare source evidence</button><button class="secondary-button" type="button" data-route-button="home">Skip for now</button>';
  else if(kind==="conflict"&&route==="search")actions='<button class="primary-button" type="button" data-reset-state>Compare cited sources</button>';
  else actions=`<button class="primary-button" type="button" data-reset-state>${kind==="empty"&&route==="search"?"Ask a question":"Retry"}</button>`;
  const loading=kind==="loading"?'<div class="grid" aria-label="Loading"><div class="skeleton wide"></div><div class="skeleton mid"></div><div class="skeleton card-height"></div></div>':"";
  return `<section class="card state-card ${klass}" ${klass?'role="alert"':""}><div class="state-icon" aria-hidden="true">${icon}</div><h2>${title}</h2><p>${copy}</p>${preserved}${loading}<div class="state-actions">${actions}</div></section>`;
}
function home(data){
  const saved=state.householdData,reminders=saved?.reminders||[],documents=saved?.documents||[],pending=state.ocrCandidate;
  const reminderRows=reminders.map(x=>`<li class="record-item"><span class="item-icon" aria-hidden="true">⏱</span><span class="item-copy"><strong>${esc(x.title)}</strong><small>Due ${esc(new Date(`${x.due_at}T00:00:00`).toLocaleDateString("en-NZ"))}</small></span><span class="pill">Confirmed</span></li>`).join("");
  return `<div class="page">${pageHead("Good evening","Everything important, easier to find.","A calm view of confirmed household records and dates.",'<button class="primary-button" type="button" data-route-button="add">Add information</button>')}${pending?`<section class="card hero-card"><p class="eyebrow">Your next step</p><div class="hero-row"><div><h2>One OCR suggestion needs confirmation</h2><p>Check it against the extracted source evidence before creating a reminder.</p></div><button class="primary-button" type="button" data-route-button="review">Review suggestion</button></div></section>`:""}<div class="grid two" style="margin-top:18px"><section class="card"><div class="section-head"><h2>Confirmed reminders</h2><a href="#household" data-route="household">Household settings</a></div><ul class="action-list">${reminderRows||'<li class="muted">No confirmed renewal or expiry dates yet.</li>'}</ul></section><section class="card"><p class="eyebrow">Household overview</p><span class="metric">${documents.length}</span><span class="metric-label">confirmed local records</span><hr style="border:0;border-top:1px solid var(--border);margin:22px 0"><p><span class="pill">${reminders.length} upcoming reminder${reminders.length===1?"":"s"}</span></p><p class="muted">Local manual-upload tests retain confirmed metadata and OCR text, not the temporary source file.</p></section></div></div>`
}
function records(data){
  const rows=data[state.recordTab];
  const detail=state.recordDetail?`<section class="card detail-card" aria-labelledby="detail-title"><p class="eyebrow">Representative detail</p><h2 id="detail-title" tabindex="-1">${esc(state.recordDetail.name)}</h2><p>${esc(state.recordDetail.detail)}</p><p class="muted">This synthetic detail demonstrates a destination only. No source is opened or saved.</p><button class="secondary-button" type="button" data-close-detail>Back to ${esc(state.recordTab)}</button></section>`:"";
  return `<div class="page">${pageHead("Records","Your household, not a maze of folders.","Browse only the people, home and vehicle information available to you.",'<button class="primary-button" type="button" data-route-button="add">Add record</button>')}<section class="card"><div class="tabs" role="tablist" aria-label="Record types">${[["people","People"],["home","Home"],["vehicles","Vehicles"]].map(([id,label])=>`<button class="tab" id="tab-${id}" role="tab" aria-selected="${state.recordTab===id}" aria-controls="panel-records" tabindex="${state.recordTab===id?0:-1}" data-tab="${id}">${label}</button>`).join("")}</div><div id="panel-records" role="tabpanel" aria-labelledby="tab-${state.recordTab}" tabindex="0"><ul class="record-list">${rows.map(x=>item(x,"Open",`data-record="${x.id}"`)).join("")}</ul></div></section>${detail}</div>`
}
function add(){
  const categories=state.householdData?.categories||[];
  const feedback=state.ocrError?`<div class="status-strip auth-error" role="alert"><span aria-hidden="true">!</span><div><strong>Document not processed</strong><br>${esc(state.ocrError)}</div></div>`:"";
  return `<div class="page">${pageHead("Add information","Choose one document to organise.","The local test sends a temporary copy to isolated PaddleOCR, deletes it after processing, and saves nothing until you confirm.",'<button class="secondary-button" type="button" data-route-button="connections">Connections</button>')}<div class="grid two"><section class="card"><span class="item-icon" aria-hidden="true">GD</span><h2 style="margin-top:14px">Google Drive</h2><p>Exact-file Google Picker access remains the target. It needs your Google Cloud OAuth client and Picker API key.</p><button class="secondary-button" type="button" disabled>Credentials required</button><p class="muted">No broad Drive scope will be substituted.</p></section><section class="card"><span class="item-icon" aria-hidden="true">↑</span><h2 style="margin-top:14px">PDF or photo</h2><p>Use a fictional or non-sensitive PDF, JPEG or PNG, up to 15 MB and 20 pages.</p>${categories.length?`<form data-ocr-upload><div class="field"><label for="ocr-file">Choose document</label><input id="ocr-file" name="file" type="file" accept="application/pdf,image/jpeg,image/png" required></div><div class="field"><label for="ocr-category">Category</label><select id="ocr-category" name="category" required>${categories.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></div><button class="primary-button" type="submit" ${state.ocrBusy?"disabled":""}>${state.ocrBusy?"Reading document…":"Read with PaddleOCR"}</button></form>`:'<p>Create your household first so the confirmed record has a category.</p><button class="primary-button" type="button" data-route-button="household">Set up household</button>'}${feedback}</section></div><div class="status-strip" style="margin-top:18px"><span aria-hidden="true">i</span><div><strong>Confirmation required</strong><br>OCR confidence is advisory. Dates, providers and identifiers are not saved until you review and confirm them.</div></div></div>`
}
function connections(){
  const cards=dataAdapter.getConnectors().map(c=>{const preview=state.connectorPreview[c.id];return `<section class="card connection-card"><div class="connection-heading"><span class="item-icon" aria-hidden="true">${c.badge}</span><div><h2>${c.name}</h2><span class="pill">${preview?"Preview connected":"Not connected"}</span></div></div><p><strong>Access:</strong> ${c.access}</p><p class="muted">Selection method: ${c.picker}. Family Documents would store a provider file ID, version and derived metadata—not silently scan the account.</p><ul><li>No whole-drive background scan</li><li>No file deletion or moving</li><li>Disconnect stops future access; originals remain with you</li></ul><button class="${preview?"secondary-button":"primary-button"}" type="button" data-connector-preview="${c.id}">${preview?"Disconnect preview":"Preview connection"}</button>${preview?'<p class="status-strip" role="status">Preview only — no OAuth token or provider account exists.</p>':""}</section>`}).join("");
  return `<div class="page">${pageHead("Connections","Choose where original files stay.","Connect only the provider you use. Live sign-in remains disabled until the security gates pass.")}<div class="grid two">${cards}</div><section class="card privacy-note"><p class="eyebrow">Important privacy boundary</p><h2>BYO storage does not mean zero processing</h2><p>Originals remain in your provider, but confirmed metadata, extracted text and reminders would still be sensitive Family Documents data. The live product must explain and protect that boundary.</p></section></div>`
}
function suggestedFields(candidate){
  const text=candidate?.text||"",lower=text.toLowerCase();let documentType="Household document",provider="",criticalDate="";
  if(/insurance|policy|premium/.test(lower)){documentType="Insurance policy";provider=/tower/.test(lower)?"Tower":""}
  else if(/wof|warrant of fitness/.test(lower)){documentType="Vehicle WOF";provider=/nzta|waka kotahi/.test(lower)?"NZTA":""}
  else if(/warranty|receipt/.test(lower)){documentType="Receipt or warranty"}
  const numeric=text.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](20\d{2})\b/);
  if(numeric){const [,day,month,year]=numeric;criticalDate=`${year}-${month.padStart(2,"0")}-${day.padStart(2,"0")}`}
  return {documentType,provider,criticalDate};
}
function review(){
  const candidate=state.ocrCandidate;
  if(!candidate)return `<div class="page">${pageHead("Review","No pending suggestion.","Choose a PDF or photo first.")}<section class="card state-card"><h2>Nothing to review</h2><button class="primary-button" type="button" data-route-button="add">Add a document</button></section></div>`;
  const suggestion=suggestedFields(candidate),categories=state.householdData?.categories||[],excerpt=candidate.text.slice(0,1800);
  return `<div class="page">${pageHead("OCR suggestion","Check the evidence, then confirm.","Nothing below is authoritative until you submit this form.")}<div class="grid two review-grid"><section class="card source-card" aria-label="OCR source evidence"><p class="eyebrow">Temporary source evidence</p><h2>${esc(candidate.file_name)}</h2><p class="muted">${esc(candidate.engine)} · ${candidate.pages.length} page(s) · mean confidence ${Math.round(candidate.mean_confidence*100)}% · SHA-256 ${esc(candidate.source.sha256.slice(0,12))}…</p><div class="source-preview"><pre style="white-space:pre-wrap;font:inherit">${esc(excerpt)}</pre></div><p class="muted">The temporary file was deleted by the OCR service. This text remains in browser memory until confirmed or rejected.</p></section><section class="card"><p class="eyebrow">Suggested information</p><h2>Confirm this record</h2><form class="review-fields" data-extraction-confirm><div class="field"><label for="document-title">Record title</label><input id="document-title" name="title" value="${esc(candidate.file_name.replace(/\.[^.]+$/,""))}" maxlength="120" required></div><div class="field"><label for="confirm-category">Category</label><select id="confirm-category" name="category" required>${categories.map(x=>`<option value="${x.id}" ${x.id===candidate.category_id?"selected":""}>${esc(x.name)}</option>`).join("")}</select></div><div class="field"><label for="document-type">Document type</label><input id="document-type" name="documentType" value="${esc(suggestion.documentType)}" maxlength="80" required></div><div class="field"><label for="provider">Provider</label><input id="provider" name="provider" value="${esc(suggestion.provider)}" maxlength="120"></div><div class="field"><label for="critical-date">Renewal or expiry date</label><input id="critical-date" name="criticalDate" type="date" value="${esc(suggestion.criticalDate)}"><small>Leave blank when the source does not clearly support a date.</small></div><label class="confirmation-check"><input name="confirmed" type="checkbox" required> I checked these values against the OCR evidence.</label><span class="pill attention">● Human confirmation required</span><button class="primary-button" type="submit">Confirm record and reminder</button><button class="text-button skip-action" type="button" data-route-button="add">Keep reviewing later</button><button class="secondary-button reject-action" type="button" data-reject-ocr>Reject and discard</button></form></section></div></div>`
}
function search(){
  const result=state.searchResult,view=buildSearchView(result,state.selectedSourceId);
  let body='<section class="card state-card"><div class="state-icon" aria-hidden="true">⌕</div><h2>Try a natural question</h2><p>For example: “When does our house insurance renew?” or “When is the Toyota WOF due?”</p></section>';
  if(result?.kind==="abstain")body=`<section class="card state-card"><div class="state-icon" aria-hidden="true">?</div><h2>No supported answer found</h2><p>${esc(result.message)} Your query is preserved so you can refine it.</p><button class="secondary-button" type="button" data-focus-query>Refine question</button></section>`;
  if(view.kind==="results"){
    const first=view.sources[0];
    body=`<div class="grid two"><section class="card"><p class="eyebrow">Answer</p><h2>${esc(view.headline)}</h2><p>This answer is limited to the cited synthetic source.</p><button class="secondary-button" type="button" data-open-source="${first.id}">Open answer source</button></section>${sourceList(view.sources)}</div><div id="source-detail-slot"></div>`;
  }
  if(view.kind==="conflict"){
    body=`<section class="card state-card error" role="alert"><div class="state-icon" aria-hidden="true">≠</div><p class="eyebrow">Conflict</p><h2>${esc(view.headline)}</h2><p>No combined answer has been generated. Open each exact synthetic source and compare its evidence.</p></section><div class="grid two" style="margin-top:18px">${sourceList(view.sources)}</div><div id="source-detail-slot"></div>`;
  }
  return `<div class="page">${pageHead("Search","Ask about your household information.","Answers show the exact synthetic source used. If evidence is missing, the prototype says so.")}<form class="search-form" data-search-form><label class="sr-only" for="query">Search your household records</label><input id="query" name="query" value="${esc(state.query)}" placeholder="When does our house insurance renew?" autocomplete="off"><button class="primary-button" type="submit">Search</button></form>${body}</div>`
}
function sourceList(sources){return `<section class="card"><div class="section-head"><h2>Sources</h2><span class="pill">${sources.length} result${sources.length===1?"":"s"}</span></div><ul class="result-list">${sources.map(x=>`<li class="result-item"><span class="item-icon" aria-hidden="true">PDF</span><span class="item-copy"><strong>${esc(x.title)}</strong><small>${esc(x.meta)}<br>${esc(x.citation)}</small></span><button class="quiet-button" type="button" data-open-source="${x.id}">Open exact source</button></li>`).join("")}</ul></section>`}
function sourceDetail(source){if(!source)return '<section class="card state-card error" role="alert"><h2 id="source-title" tabindex="-1">Source unavailable</h2><p>The selected source is not in the authorised synthetic result set. Nothing was opened.</p><button class="secondary-button" type="button" data-close-source>Close</button></section>';return `<section class="card detail-card"><p class="eyebrow">Exact synthetic source</p><h2 id="source-title" tabindex="-1">${esc(source.title)}</h2><p><strong>${esc(source.citation)}</strong></p><p class="highlight"><strong>Evidence:</strong> ${esc(source.answer)}</p><button class="secondary-button" type="button" data-close-source>Close source</button></section>`}
function auth(){
  const signup=state.authMode==="signup";
  const feedback=state.authError?`<div class="status-strip auth-error" role="alert"><span aria-hidden="true">!</span><div><strong>Sign-in was not completed</strong><br>${esc(state.authError)}</div></div>`:state.authMessage?`<div class="status-strip" role="status"><span aria-hidden="true">✓</span><div><strong>Account step completed</strong><br>${esc(state.authMessage)}</div></div>`:"";
  return `<div class="auth-page"><section class="auth-intro"><span class="brand-mark" aria-hidden="true">FD</span><p class="eyebrow">Family Documents</p><h1>${signup?"Create your family space":"Welcome back"}</h1><p>${signup?"Create a synthetic local account, confirm its email, then sign in.":"Sign in to organise the information your household depends on."}</p><ul><li>Original files stay in storage you choose</li><li>Important values require confirmation</li><li>Family access is explicit and revocable</li></ul></section><section class="card auth-card"><div class="auth-tabs" role="tablist" aria-label="Account action"><button role="tab" aria-selected="${!signup}" data-auth-mode="signin">Sign in</button><button role="tab" aria-selected="${signup}" data-auth-mode="signup">Create account</button></div><button class="google-button" type="button" disabled aria-describedby="google-status"><span aria-hidden="true">G</span>Continue with Google</button><p id="google-status" class="muted auth-provider-note">Google sign-in is not connected yet.</p><div class="divider"><span>use local email</span></div><form class="auth-form" data-auth-form>${signup?'<div class="field"><label for="auth-name">Your name</label><input id="auth-name" name="name" autocomplete="name" required></div>':""}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="${signup?"new-password":"current-password"}" minlength="14" maxlength="128" required><small>${signup?"Use at least 14 characters. Confirm the message in local Mailpit before signing in.":"Only a verified local synthetic account can sign in."}</small></div><button class="primary-button" type="submit" ${state.authBusy?"disabled":""}>${state.authBusy?"Please wait…":signup?"Create local account":"Sign in with email"}</button></form>${feedback}<p class="auth-boundary">Local test only — credentials go to <code>127.0.0.1:55321</code>. Tokens remain in memory and are cleared on reload or sign-out.</p></section></div>`;
}
function household(){
  const data=state.householdData;
  if(state.dataBusy)return `<div class="page">${pageHead("Household settings","Loading your private household…","Access checks are applied before names or counts appear.")}<section class="card state-card"><h2>Loading</h2><p>Please wait.</p></section></div>`;
  if(state.dataError)return `<div class="page">${pageHead("Household settings","Household data is unavailable.","Nothing was changed.")}<section class="card state-card error" role="alert"><h2>Could not load household</h2><p>${esc(state.dataError)}</p><button class="primary-button" type="button" data-retry-household>Retry</button></section></div>`;
  if(!data||data.needs_setup)return `<div class="page">${pageHead("Create your household","Start with one private family space.","You become the owner. Default categories are added automatically.",'<button class="secondary-button" type="button" data-preview-signout>Sign out</button>')}<div class="grid two"><form class="card" data-household-setup><p class="eyebrow">New household</p><h2>Name your family space</h2><div class="field"><label for="household-name">Household name</label><input id="household-name" name="household" maxlength="80" value="My household" required></div><div class="field"><label for="display-name">Your display name</label><input id="display-name" name="displayName" maxlength="80" required></div><button class="primary-button" type="submit">Create household</button></form><section class="card"><p class="eyebrow">Already invited?</p><h2>Join a family space</h2><p>If an owner invited this verified email address, accept it here.</p><button class="secondary-button" type="button" data-accept-invitation>Accept my invitation</button><p class="muted">The invitation must match your signed-in email and still be valid.</p></section></div></div>`;
  const current=data.current_user||{};
  const isAdmin=["owner","family_admin"].includes(current.role);
  const roleLabel=x=>String(x).replaceAll("_"," ").replace(/\b\w/g,c=>c.toUpperCase());
  const memberRows=(data.members||[]).map(x=>`<li class="record-item"><span class="item-icon" aria-hidden="true">${esc((x.display_name||x.email).slice(0,2).toUpperCase())}</span><span class="item-copy"><strong>${esc(x.display_name||x.email)}</strong><small>${esc(roleLabel(x.role))}</small></span>${x.id===current.id?'<span class="pill">You</span>':""}</li>`).join("");
  const inviteRows=(data.invitations||[]).filter(x=>x.status==="pending").map(x=>`<li class="record-item"><span class="item-icon" aria-hidden="true">✉</span><span class="item-copy"><strong>${esc(x.email)}</strong><small>${esc(roleLabel(x.role))} · expires ${esc(new Date(x.expires_at).toLocaleDateString("en-NZ"))}</small></span><span class="pill attention">Pending</span></li>`).join("");
  const categories=data.categories||[], documents=data.documents||[], members=(data.members||[]).filter(x=>x.id!==current.id&&x.status==="active");
  const adminForms=isAdmin?`<form class="invite-form" data-invite-form><h3>Invite someone</h3><div class="field"><label for="invite-email">Email address</label><input id="invite-email" name="email" type="email" required></div><div class="field"><label for="invite-role">Starting role</label><select id="invite-role" name="role"><option value="adult_member">Adult member</option><option value="family_admin">Family admin</option><option value="contributor">Contributor</option><option value="viewer">Viewer</option></select></div><button class="primary-button" type="submit">Create invitation</button><p class="muted">Local testing records a seven-day invitation. Email delivery is not enabled yet.</p></form>`:"";
  const accessForm=isAdmin?`<form data-access-form><p class="eyebrow">Document access</p><h2>Share one document</h2><div class="field"><label for="access-document">Document</label><select id="access-document" name="document" required><option value="">Choose a document</option>${documents.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join("")}</select></div><div class="field"><label for="access-person">Member</label><select id="access-person" name="member" required><option value="">Choose a member</option>${members.map(x=>`<option value="${x.id}">${esc(x.display_name||x.email)}</option>`).join("")}</select></div><div class="field"><label for="access-level">Access</label><select id="access-level" name="access"><option value="view">Can view</option><option value="contribute">Can contribute</option><option value="manage">Can manage</option><option value="none">Remove access</option></select></div><button class="secondary-button" type="submit" ${!documents.length||!members.length?"disabled":""}>Save document access</button></form>`:`<div class="status-strip"><span aria-hidden="true">i</span><div><strong>Default deny</strong><br>You only see documents explicitly available to you.</div></div>`;
  return `<div class="page">${pageHead("Household settings","People, access and categories.","Saved in the isolated local Family Documents database.",'<button class="secondary-button" type="button" data-preview-signout>Sign out</button>')}<div class="grid two"><section class="card"><p class="eyebrow">Family members</p><h2>${esc(data.household.name)}</h2><ul class="record-list member-list">${memberRows}${inviteRows}</ul>${adminForms}</section><section class="card">${accessForm}</section></div><div class="grid two" style="margin-top:18px"><section class="card category-card"><div class="section-head"><div><p class="eyebrow">Organisation</p><h2>Categories</h2></div><span class="pill">${categories.length} available</span></div><div class="category-list">${categories.map(x=>`<span class="category-chip">${esc(x.name)}</span>`).join("")}</div>${isAdmin?`<form class="category-form" data-category-form><div class="field"><label for="category-name">Add a custom category</label><input id="category-name" name="category" maxlength="40" placeholder="For example, School" required></div><button class="secondary-button" type="submit">Add category</button></form>`:""}</section><section class="card"><p class="eyebrow">Document metadata</p><h2>Permission test records</h2><ul class="record-list">${documents.map(x=>`<li class="record-item"><span class="item-icon" aria-hidden="true">DOC</span><span class="item-copy"><strong>${esc(x.title)}</strong><small>Metadata only · no file uploaded</small></span></li>`).join("")||'<li class="muted">No document metadata yet.</li>'}</ul><form data-document-form><div class="field"><label for="document-title">Document title</label><input id="document-title" name="title" maxlength="120" placeholder="For example, House insurance policy" required></div><div class="field"><label for="document-category">Category</label><select id="document-category" name="category" required>${categories.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></div><button class="secondary-button" type="submit">Add metadata record</button></form></section></div></div>`;
}
const renderers={auth,home,records,add,review,search,connections,household};
function render({focus=false,tabFocus=false,detailFocus=false}={}){
  document.body.classList.toggle("auth-mode",state.route==="auth");
  document.querySelectorAll("[data-route]").forEach(a=>{const current=a.dataset.route===state.route;a.toggleAttribute("aria-current",current);if(current)a.setAttribute("aria-current","page")});
  const data=dataAdapter.getHousehold();
  screen.innerHTML=state.scenario==="default"||state.route==="auth"?renderers[state.route](data):`<div class="page">${pageHead("Preview state",state.route[0].toUpperCase()+state.route.slice(1),"Representative recovery for this specific task.")}${stateView(state.route,state.scenario)}</div>`;
  document.title=`${state.route[0].toUpperCase()+state.route.slice(1)} — Family Documents prototype`;bindDynamic();
  if(tabFocus)screen.querySelector(`[data-tab="${state.recordTab}"]`)?.focus();else if(detailFocus)screen.querySelector("#detail-title,#source-title")?.focus();else if(focus)screen.querySelector("h1")?.focus();
}
function navigate(route,{focus=true}={}){state.route=route;state.recordDetail=null;state.selectedSourceId=null;state.sourceInvoker=null;location.hash=route;render({focus})}
async function loadHousehold(){
  state.dataBusy=true;state.dataError="";if(state.route==="household")render();
  try{state.householdData=await window.familyPassportData.snapshot()}
  catch(error){state.dataError=error.status===401?"Your session expired. Sign in again.":"The isolated household service could not be reached."}
  finally{state.dataBusy=false;if(state.route==="household")render({focus:true})}
}
function activateTab(id){state.recordTab=id;state.recordDetail=null;render({tabFocus:true});announce(`${id} records selected`)}
function bindDynamic(){
  screen.querySelectorAll("[data-route]").forEach(x=>x.addEventListener("click",e=>{e.preventDefault();navigate(x.dataset.route)}));screen.querySelectorAll("[data-route-button]").forEach(x=>x.addEventListener("click",()=>navigate(x.dataset.routeButton)));
  screen.querySelector("[data-state-help]")?.addEventListener("click",e=>openHelp(e.currentTarget));screen.querySelector("[data-reset-state]")?.addEventListener("click",()=>{state.scenario="default";scenarioSelect.value="default";render({focus:true});announce("Populated prototype view restored")});
  screen.querySelectorAll("[data-tab]").forEach(tab=>{tab.addEventListener("click",()=>activateTab(tab.dataset.tab));tab.addEventListener("keydown",e=>{const tabs=["people","home","vehicles"];let i=tabs.indexOf(state.recordTab);if(e.key==="ArrowRight")i=(i+1)%3;else if(e.key==="ArrowLeft")i=(i+2)%3;else if(e.key==="Home")i=0;else if(e.key==="End")i=2;else return;e.preventDefault();activateTab(tabs[i])})});
  screen.querySelectorAll("[data-home-action]").forEach(b=>b.addEventListener("click",()=>{const action=dataAdapter.getHousehold().actions.find(x=>x.id===b.dataset.homeAction);if(action.tab)state.recordTab=action.tab;navigate(action.destination)}));
  screen.querySelectorAll("[data-record]").forEach(b=>b.addEventListener("click",()=>{state.recordDetail=dataAdapter.getHousehold()[state.recordTab].find(x=>x.id===b.dataset.record);render({detailFocus:true});announce("Representative record detail opened")}));screen.querySelector("[data-close-detail]")?.addEventListener("click",()=>{const id=state.recordDetail.id;state.recordDetail=null;render();screen.querySelector(`[data-record="${id}"]`)?.focus()});
  screen.querySelector("[data-search-form]")?.addEventListener("submit",e=>{e.preventDefault();state.query=new FormData(e.currentTarget).get("query").trim();state.searchResult=dataAdapter.search(state.query);state.selectedSourceId=null;state.sourceInvoker=null;render({focus:true});announce(state.searchResult.kind==="results"?"Cited synthetic results available":state.searchResult.kind==="conflict"?"Conflicting sources require comparison":"No supported answer found")});screen.querySelector("[data-focus-query]")?.addEventListener("click",()=>screen.querySelector("#query")?.focus());
  screen.querySelectorAll("[data-open-source]").forEach(b=>b.addEventListener("click",()=>openSource(b)));
  screen.querySelector("[data-review-form]")?.addEventListener("submit",e=>{e.preventDefault();dataAdapter.submit();screen.innerHTML=`<div class="page">${pageHead("Confirmed","Renewal confirmed in this prototype view.",MOCK_NOTICE)}<section class="card state-card"><div class="state-icon" aria-hidden="true">✓</div><h2>Information confirmed</h2><p>A real product would create a reminder only after this explicit confirmation.</p><button class="primary-button" type="button" data-route-button="home">Return home</button></section></div>`;bindDynamic();screen.querySelector("h1")?.focus();announce("Synthetic information confirmed")});screen.querySelector("[data-reject]")?.addEventListener("click",()=>{announce("Suggestion rejected; original synthetic source unchanged");navigate("home")});
  screen.querySelector("[data-ocr-upload]")?.addEventListener("submit",async e=>{e.preventDefault();if(state.ocrBusy)return;const form=new FormData(e.currentTarget),file=form.get("file"),categoryId=String(form.get("category")||"");state.ocrBusy=true;state.ocrError="";render({focus:true});try{const result=await window.familyPassportOcr.process(file);state.ocrCandidate={...result,category_id:categoryId};announce("OCR suggestion ready for review");navigate("review");return}catch(error){state.ocrError=error.message||"OCR could not process this file.";announce(state.ocrError)}finally{state.ocrBusy=false}render({focus:true})});
  screen.querySelector("[data-extraction-confirm]")?.addEventListener("submit",async e=>{e.preventDefault();const candidate=state.ocrCandidate;if(!candidate)return;const form=new FormData(e.currentTarget);if(form.get("confirmed")!=="on")return;state.dataBusy=true;try{await window.familyPassportData.confirmExtraction({document_title:String(form.get("title")||"").trim(),category:String(form.get("category")||""),source_name:candidate.file_name,source_sha256:candidate.source.sha256,source_mime_type:candidate.source.mime_type,confirmed_text:candidate.text,confirmed_document_type:String(form.get("documentType")||"").trim(),confirmed_provider:String(form.get("provider")||"").trim(),confirmed_critical_date:String(form.get("criticalDate")||"")||null,mean_confidence:candidate.mean_confidence});state.ocrCandidate=null;await loadHousehold();announce("Confirmed record and reminder saved");navigate("home");return}catch{state.dataError="The confirmed record could not be saved.";announce(state.dataError);navigate("household")}finally{state.dataBusy=false}});
  screen.querySelector("[data-reject-ocr]")?.addEventListener("click",()=>{state.ocrCandidate=null;state.ocrError="";announce("OCR suggestion discarded; no record was saved");navigate("add")});
  screen.querySelectorAll("[data-mock-action]").forEach(b=>b.addEventListener("click",()=>{b.textContent="Prototype only — no file selected";announce("No file selected or stored")}));
  screen.querySelectorAll("[data-connector-preview]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.connectorPreview;state.connectorPreview[id]=!state.connectorPreview[id];render({focus:true});announce(state.connectorPreview[id]?"Connection preview enabled; no account was contacted":"Connection preview removed")}));
  screen.querySelectorAll("[data-auth-mode]").forEach(b=>b.addEventListener("click",()=>{state.authMode=b.dataset.authMode;state.authReady=false;state.authMessage="";state.authError="";render({focus:true})}));
  screen.querySelector("[data-auth-form]")?.addEventListener("submit",async e=>{e.preventDefault();if(state.authBusy)return;const form=new FormData(e.currentTarget);const email=String(form.get("email")||"").trim();const password=String(form.get("password")||"");const name=String(form.get("name")||"").trim();state.authBusy=true;state.authMessage="";state.authError="";const submit=e.currentTarget.querySelector('button[type="submit"]');if(submit){submit.disabled=true;submit.textContent="Please wait…"}try{await window.familyPassportAuth.health();if(state.authMode==="signup"){await window.familyPassportAuth.signUp({email,password,name});state.authMode="signin";state.authMessage="Confirmation sent. Open local Mailpit at 127.0.0.1:55324, confirm the address, then sign in.";announce("Confirmation email sent to local Mailpit")}else{const result=await window.familyPassportAuth.signIn({email,password});state.authUser=result.user;state.previewSignedIn=true;state.authReady=true;await loadHousehold();announce("Signed in with verified local email");navigate("household");return}}catch(error){state.authError=error.status===400||error.status===422?"Check the email, password and confirmation status, then try again.":"The local authentication or household service is unavailable. Start it and retry.";announce(state.authError)}finally{state.authBusy=false}render({focus:true})});
  screen.querySelector("[data-preview-signout]")?.addEventListener("click",async()=>{await window.familyPassportAuth.signOut();state.previewSignedIn=false;state.authReady=false;state.authUser=null;state.authMessage="You have signed out.";navigate("auth")});
  screen.querySelector("[data-retry-household]")?.addEventListener("click",loadHousehold);
  screen.querySelector("[data-household-setup]")?.addEventListener("submit",async e=>{e.preventDefault();const form=new FormData(e.currentTarget);state.dataBusy=true;render();try{state.householdData=await window.familyPassportData.bootstrap(String(form.get("household")||""),String(form.get("displayName")||""));announce("Household created")}catch{state.dataError="The household could not be created."}finally{state.dataBusy=false;render({focus:true})}});
  screen.querySelector("[data-accept-invitation]")?.addEventListener("click",async()=>{state.dataBusy=true;render();try{state.householdData=await window.familyPassportData.acceptInvitation();announce("Invitation accepted")}catch{state.dataError="No valid invitation matched this signed-in email."}finally{state.dataBusy=false;render({focus:true})}});
  screen.querySelector("[data-invite-form]")?.addEventListener("submit",async e=>{e.preventDefault();const form=new FormData(e.currentTarget);try{await window.familyPassportData.inviteMember(String(form.get("email")||"").trim(),String(form.get("role")||"viewer"));await loadHousehold();announce("Seven-day invitation saved; local email delivery is not enabled") }catch{state.dataError="The invitation could not be created.";render({focus:true})}});
  screen.querySelector("[data-category-form]")?.addEventListener("submit",async e=>{e.preventDefault();const value=String(new FormData(e.currentTarget).get("category")||"").trim();try{await window.familyPassportData.createCategory(value);await loadHousehold();announce("Custom category saved") }catch{state.dataError="That category could not be saved. It may already exist.";render({focus:true})}});
  screen.querySelector("[data-document-form]")?.addEventListener("submit",async e=>{e.preventDefault();const form=new FormData(e.currentTarget);try{await window.familyPassportData.createDocument(String(form.get("title")||"").trim(),String(form.get("category")||""));await loadHousehold();announce("Document metadata saved; no file was uploaded") }catch{state.dataError="The document metadata could not be saved.";render({focus:true})}});
  screen.querySelector("[data-access-form]")?.addEventListener("submit",async e=>{e.preventDefault();const form=new FormData(e.currentTarget);try{await window.familyPassportData.setDocumentAccess(String(form.get("document")||""),String(form.get("member")||""),String(form.get("access")||"view"));await loadHousehold();announce("Document access updated") }catch{state.dataError="Document access could not be updated.";render({focus:true})}});
}
function openSource(invoker){
  state.sourceInvoker=invoker;state.selectedSourceId=invoker.dataset.openSource||null;
  const slot=screen.querySelector("#source-detail-slot"),view=buildSearchView(state.searchResult,state.selectedSourceId);
  if(!slot)return;slot.innerHTML=sourceDetail(view.selectedSource);slot.querySelector("#source-title")?.focus();
  slot.querySelector("[data-close-source]")?.addEventListener("click",()=>{slot.innerHTML="";state.selectedSourceId=null;const prior=state.sourceInvoker;state.sourceInvoker=null;restoreInvoker(prior)});
  announce(view.selectedSource?"Exact synthetic source opened":"Source unavailable");
}
document.querySelectorAll("[data-route]").forEach(x=>x.addEventListener("click",e=>{e.preventDefault();navigate(x.dataset.route)}));document.querySelectorAll("[data-route-button]").forEach(x=>x.addEventListener("click",()=>navigate(x.dataset.routeButton)));
scenarioToggle.addEventListener("click",()=>{const open=scenarioPanel.hidden;scenarioPanel.hidden=!open;scenarioToggle.setAttribute("aria-expanded",String(open));if(open)scenarioSelect.focus()});document.querySelector("#scenario-close").addEventListener("click",()=>{scenarioPanel.hidden=true;scenarioToggle.setAttribute("aria-expanded","false");scenarioToggle.focus()});scenarioSelect.addEventListener("change",()=>{state.scenario=scenarioSelect.value;render({focus:true})});document.querySelectorAll("[data-help]").forEach(b=>b.addEventListener("click",e=>openHelp(e.currentTarget)));
window.addEventListener("hashchange",()=>{const route=location.hash.slice(1);if(renderers[route]&&route!==state.route){state.route=!state.previewSignedIn&&route!=="auth"?"auth":route;render({focus:true})}});const requestedRoute=location.hash.slice(1);state.route=state.previewSignedIn&&renderers[requestedRoute]?requestedRoute:"auth";render();
